def unknown_bases():
    """Don't emit when a base of the cause's class could not be inferred."""
    from lala import bala  # pylint: disable=import-outside-toplevel

    class MyException(bala):
        """Whether this derives from BaseException cannot be determined."""

    try:
        pass
    except MyException as exc:
        raise IndexError from exc

def has_known_bases(
    klass: nodes.ClassDef, context: InferenceContext | None = None
) -> bool:
    """Return true if all base classes of a class could be inferred."""
    try:
        return klass._all_bases_known  # type: ignore[no-any-return]
    except AttributeError:
        pass
    for base in klass.bases:
        result = safe_infer(base, context=context)
        if (
            not isinstance(result, nodes.ClassDef)
            or result is klass
            or not has_known_bases(result, context=context)
        ):
            klass._all_bases_known = False
            return False
    klass._all_bases_known = True
    return True

