def outer():
    """No redefined-loop-name for variables in nested scopes"""
    for i1 in range(5):
        def inner():
            """No warning, because i has a new scope"""
            for i1 in range(3):
                print(i1)
        print(i1)
        inner()


def outer2():
    """Similar, but with an assignment instead of homonymous loop variables"""
    for i1 in range(5):
        def inner():
            """No warning, because i has a new scope"""
            for _ in range(3):
                i1 = 0
                print(i1)
        print(i1)
        inner()

